// Tests for the edges area: path_geometry.rs's unit test, hand-checked fills, and parity data generated
// from the real tiny-skia 0.12 crate (a recording blitter fed by scan::path::fill_path and
// scan::path_aa::fill_path, and path_geometry::chop_mono_cubic_at_x/y).

func TestChopCubicAtYExtrema1(t *testing.T) {
	src := [4]Point{{10, 20}, {67, 437}, {298, 213}, {401, 214}}
	var dst [10]Point
	n := chopCubicAtYExtrema(&src, &dst)
	if n != 2 {
		t.Fatalf("n = %d, want 2", n)
	}
	want := [10]Point{
		{10, 20},
		{37.508274, 221.24475},
		{105.541855, 273.19803},
		{180.15599, 273.19803},
		{259.80502, 273.19803},
		{346.9527, 213.99666},
		{400.30844, 213.99666},
		{400.53958, 213.99666},
		{400.7701, 213.99777},
		{401, 214},
	}
	if dst != want {
		t.Fatalf("dst = %v, want %v", dst, want)
	}
}

func TestNewLineEdge(t *testing.T) {
	e, ok := newLineEdge(Point{0, 10}, Point{0, 0}, 0)
	if !ok {
		t.Fatal("vertical line rejected")
	}
	want := lineEdge{prev: edgeNone, next: edgeNone, x: 0, dx: 0, firstY: 0, lastY: 9, winding: -1}
	if e != want {
		t.Fatalf("edge = %+v, want %+v", e, want)
	}
	// x = 1/2 + y/2: at the first pixel center (y = 0.5) x is 0.75.
	e, _ = newLineEdge(Point{0.5, 0}, Point{5.5, 10}, 0)
	if e.dx != fdot16One/2 || e.x != fdot16One*3/4 || e.firstY != 0 || e.lastY != 9 || e.winding != 1 {
		t.Fatalf("edge = %+v", e)
	}
	if _, ok := newLineEdge(Point{0, 1.2}, Point{10, 1.4}, 0); ok {
		t.Fatal("zero-height line accepted")
	}
}

// recordingBlitter records blit calls in the format of the Rust generator.
type recordingBlitter struct {
	unreachableBlitter
	out strings.Builder
}

func (r *recordingBlitter) blitH(x, y, width uint32) { fmt.Fprintf(&r.out, "H%d,%d,%d;", x, y, width) }

func (r *recordingBlitter) blitAntiH(x, y uint32, aa []uint8, runs []uint16) {
	fmt.Fprintf(&r.out, "A%d,%d", x, y)
	for i := 0; runs[i] != 0; i += int(runs[i]) {
		fmt.Fprintf(&r.out, ",%d:%d", runs[i], aa[i])
	}
	r.out.WriteByte(';')
}

func recordFill(path *Path, fillRule FillRule, clip screenIntRect, aa bool) string {
	var r recordingBlitter
	if aa {
		fillPathAA(path, fillRule, clip, &r)
	} else {
		fillPath(path, fillRule, clip, &r)
	}
	return r.out.String()
}

func TestFillPathRect(t *testing.T) {
	path := PathFromRect(Rect{10, 10, 20, 15})
	clip := screenIntRectFromXYWHSafe(0, 0, 100, 100)
	var want, wantAA strings.Builder
	for y := 10; y < 15; y++ {
		fmt.Fprintf(&want, "H10,%d,10;", y)
		// 4 supersampled rows add 64+64+64+63 to each pixel.
		fmt.Fprintf(&wantAA, "A10,%d,10:255;", y)
	}
	for _, rule := range []FillRule{FillRuleWinding, FillRuleEvenOdd} {
		if got := recordFill(path, rule, clip, false); got != want.String() {
			t.Errorf("fillPath = %s, want %s", got, want.String())
		}
		if got := recordFill(path, rule, clip, true); got != wantAA.String() {
			t.Errorf("fillPathAA = %s, want %s", got, wantAA.String())
		}
	}
}

func TestFillPathTriangle(t *testing.T) {
	// A right triangle (0,0) (8,0) (0,8): at row center y + 0.5 the right edge is x = 7.5 - y, which
	// rounds to 8 - y.
	pb := NewPathBuilder()
	pb.MoveTo(0, 0)
	pb.LineTo(8, 0)
	pb.LineTo(0, 8)
	pb.Close()
	got := recordFill(pb.Finish(), FillRuleWinding, screenIntRectFromXYWHSafe(0, 0, 16, 16), false)
	var want strings.Builder
	for y := 0; y < 8; y++ {
		if w := 8 - y; w > 0 {
			fmt.Fprintf(&want, "H0,%d,%d;", y, w)
		}
	}
	if got != want.String() {
		t.Errorf("fillPath = %s, want %s", got, want.String())
	}
}

func TestFillPathEvenOddHole(t *testing.T) {
	pb := NewPathBuilder()
	pb.PushRect(Rect{0, 0, 6, 3})
	pb.PushRect(Rect{2, 0, 4, 3})
	path := pb.Finish()
	clip := screenIntRectFromXYWHSafe(0, 0, 10, 10)
	if got, want := recordFill(path, FillRuleEvenOdd, clip, false), "H0,0,2;H4,0,2;H0,1,2;H4,1,2;H0,2,2;H4,2,2;"; got != want {
		t.Errorf("even-odd = %s, want %s", got, want)
	}
	if got, want := recordFill(path, FillRuleWinding, clip, false), "H0,0,6;H0,1,6;H0,2,6;"; got != want {
		t.Errorf("winding = %s, want %s", got, want)
	}
}

type edgesParityWant struct {
	hash uint64
	n    int
}

type edgesParityCase struct {
	name  string
	group int  // 0: inside the clip, 1: clipped curves only, 2: clipped lines (needs the line clipper)
	libm  bool // the result depends on a cos or acos that the Windows CRT rounds off by over half an ulp
	clip  [4]uint32
	path  []uint32
	want  [4]edgesParityWant // non-AA winding, non-AA even-odd, AA winding, AA even-odd
}

func edgesParityPath(t *testing.T, cmds []uint32) *Path {
	f := func(i int) float32 { return math.Float32frombits(cmds[i]) }
	pb := NewPathBuilder()
	for i := 0; i < len(cmds); {
		switch cmds[i] {
		case 0:
			pb.MoveTo(f(i+1), f(i+2))
			i += 3
		case 1:
			pb.LineTo(f(i+1), f(i+2))
			i += 3
		case 2:
			pb.QuadTo(f(i+1), f(i+2), f(i+3), f(i+4))
			i += 5
		case 3:
			pb.CubicTo(f(i+1), f(i+2), f(i+3), f(i+4), f(i+5), f(i+6))
			i += 7
		case 4:
			pb.Close()
			i++
		default:
			t.Fatalf("bad command %d", cmds[i])
		}
	}
	return pb.Finish()
}

func fnv64(s string) uint64 {
	h := uint64(0xcbf29ce484222325)
	for i := 0; i < len(s); i++ {
		h ^= uint64(s[i])
		h *= 0x100000001b3
	}
	return h
}

func TestFillPathParity(t *testing.T) {
	for i, c := range edgesParityCases {
		path := edgesParityPath(t, c.path)
		clip, ok := screenIntRectFromXYWH(c.clip[0], c.clip[1], c.clip[2], c.clip[3])
		if !ok {
			t.Fatalf("case %d: bad clip", i)
		}
		for k, mode := range [4]struct {
			aa   bool
			rule FillRule
		}{{false, FillRuleWinding}, {false, FillRuleEvenOdd}, {true, FillRuleWinding}, {true, FillRuleEvenOdd}} {
			got := recordFill(path, mode.rule, clip, mode.aa)
			if h := fnv64(got); h != c.want[k].hash || len(got) != c.want[k].n {
				report := t.Errorf
				if c.libm {
					report = t.Logf
				}
				report("case %d (%s) aa=%v rule=%d: hash %#x len %d, want %#x len %d", i, c.name, mode.aa,
					mode.rule, h, len(got), c.want[k].hash, c.want[k].n)
			}
		}
	}
}

type chopMonoCubicCase struct {
	vertical bool
	src      []uint32
	at       uint32
	ok       bool
	dst      []uint32
}

func TestChopMonoCubicParity(t *testing.T) {
	for i, c := range chopMonoCubicCases {
		var src [4]Point
		for k := range src {
			src[k] = Point{math.Float32frombits(c.src[2*k]), math.Float32frombits(c.src[2*k+1])}
		}
		at := math.Float32frombits(c.at)
		var dst [7]Point
		var ok bool
		if c.vertical {
			ok = chopMonoCubicAtX(&src, at, &dst)
		} else {
			ok = chopMonoCubicAtY(&src, at, &dst)
		}
		if ok != c.ok {
			t.Errorf("case %d: ok = %v, want %v", i, ok, c.ok)
			continue
		}
		if !ok {
			continue
		}
		for k := range dst {
			gx, gy := math.Float32bits(dst[k].X), math.Float32bits(dst[k].Y)
			if gx != c.dst[2*k] || gy != c.dst[2*k+1] {
				t.Errorf("case %d: dst[%d] = %v, want (%v, %v)", i, k, dst[k],
					math.Float32frombits(c.dst[2*k]), math.Float32frombits(c.dst[2*k+1]))
			}
		}
	}
}

